#!/bin/bash
cd /opt/mogongfang && echo "=== 开始部署 ===" && git pull origin main && echo "✓ 代码已更新" && node init-auth-db.js && echo "✓ 数据库已初始化" && pm2 restart ticket-service auth-service && pm2 save && echo "✓ 服务已重启" && cat > /etc/nginx/sites-available/mogongfang << 'EOF' && server { listen 80; return 301 https://$host$request_uri; } server { listen 443 ssl http2; ssl_certificate /etc/nginx/ssl/nginx.crt; ssl_certificate_key /etc/nginx/ssl/nginx.key; ssl_protocols TLSv1.2 TLSv1.3; location /api/auth { proxy_pass http://localhost:3002; proxy_set_header Host $host; proxy_set_header X-Real-IP $remote_addr; } location /api { proxy_pass http://localhost:3001; proxy_set_header Host $host; proxy_set_header X-Real-IP $remote_addr; } location /health { proxy_pass http://localhost:3001/health; } } EOF && echo "✓ Nginx已配置" && nginx -t > /dev/null && systemctl restart nginx && echo "✓ Nginx已重启" && sleep 2 && echo "=== 服务状态 ===" && pm2 list && echo "=== 测试结果 ===" && curl -s http://localhost:3001/health && curl -s http://localhost:3002/health && echo "=== 部署完成 ===" && echo "现在可以测试注册和支付功能了！"
